-- org_combined
SELECT owner, tupleElement(k, 1) AS day_s, tupleElement(k, 2) AS actor,
  countIf(event_type = 'PushEvent') AS push,
  countIf(event_type = 'PullRequestEvent') AS pr,
  countIf(event_type = 'IssuesEvent') AS issues,
  countIf(event_type = 'ReleaseEvent') AS release,
  count() AS n_all,
  formatDateTime(min(created_at), '%Y-%m-%d %H:%i:%S', 'UTC') AS first_ts,
  formatDateTime(max(created_at), '%Y-%m-%d %H:%i:%S', 'UTC') AS last_ts,
  formatDateTime(minIf(created_at, event_type = 'PushEvent'), '%Y-%m-%d %H:%i:%S', 'UTC') AS first_push_ts
FROM (SELECT lower(if(position(repo_name, '/') > 0, substring(repo_name, 1, position(repo_name, '/') - 1), '')) AS owner, created_at, event_type, lower(actor_login) AS al
      FROM github_events
      WHERE owner IN ('getaccept', 'getcomputable', 'getdexter', 'getfidia', 'getfilta', 'getinflow', 'getjusto', 'getlago', 'getlark', 'getlilac', 'getreploy', 'getshogun', 'getthematic', 'getupgraded', 'getversive', 'getzep', 'gfdrr', 'giaola', 'gigs', 'gigwell', 'ginkgobioworks', 'gisaelkartea', 'gitprime', 'givegab', 'givve', 'glassflow', 'gleon', 'glideapps', 'gluenetworks', 'gobble', 'gocardless', 'gocella', 'golinks', 'gombaszog', 'gometa', 'goodcover', 'goodshape', 'goodybag', 'gophergala', 'goswap', 'gotrebol', 'goubiq', 'govly', 'grandcentrix', 'graze', 'greatquestion', 'greenruby', 'gridscale', 'groundmail', 'growthbook', 'gumloop', 'gusto', 'hackwestern', 'haplotypelabs', 'harnessrouter', 'haskell', 'healthsherpa', 'healthtech1', 'heap', 'helicone', 'hellobonsai', 'hellosign', 'helmwave', 'heritageholdings', 'heroiclabs', 'heroku', 'hestiacp', 'hexclave', 'heycanopy', 'heydoctor', 'heyrevia', 'higherme', 'highlight', 'hireart', 'hitta', 'hockeystack', 'hornetsecurity', 'housesigma', 'hubuc', 'humaans', 'humandx', 'humanloop', 'hyperbeam', 'hyperbound', 'hypercontext', 'hyperspell', 'hyperting', 'hyperweek', 'i-atros', 'icepanel', 'ideesculture', 'ideil', 'iescampanillas', 'igalia', 'imgix', 'implisense', 'inacta', 'incidentfox', 'increase', 'infisical', 'influxdata', 'infracost', 'inkeep', 'innologica', 'inpowered', 'inqre', 'insightdatascience', 'inspectify', 'inspira', 'instacart', 'instantdb', 'instawork', 'instrumentl', 'integrated-reasoning', 'intip', 'intryc', 'invofox', 'invopop', 'iomete', 'iotflows', 'iseazy', 'itschool', 'jamsocket', 'joinalfie', 'joinpantheon', 'jruby', 'juliagraphs', 'k4cg', 'kalshi', 'kangoextensions', 'karatelabs', 'kartverket', 'keepertax', 'keephq', 'kernel', 'khatabook', 'kingkupong', 'kippt', 'kiwigrid', 'knplabs', 'koertnermuth', 'kokocares', 'kraftful', 'kranushealth', 'kubeforge', 'kubesail', 'kugelaudio', 'labs64', 'lancedb', 'langdock', 'langfuse', 'lanyrd', 'laststar', 'laudspeaker', 'launchflow', 'laylo', 'ledger