        AND actor_login != '' AND NOT match(lower(actor_login), '(\\[bot\\]$|-bot$|^dependabot|^renovate|^github-actions|^greenkeeper)'))
ARRAY JOIN [(toString(toDate(created_at, 'UTC')), ''), ('', al)] AS k
GROUP BY owner, day_s, actor
ORDER BY owner, day_s, actor
LIMIT 500001
FORMAT TSVWithNames
